package com.bank.settle;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SettlementVarDemo {
    private static final Logger log = Logger.getLogger(SettlementVarDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);   // var in for-each
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        var rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00")); // infers Account
        var priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));
        var service = new SettlementService();   // infers SettlementService

        var transfers = List.of(
                new BigDecimal("45000.00"),
                new BigDecimal("12000.00"));     // infers List<BigDecimal>

        var total = service.settle(rajesh, priya, transfers);
        log.info(() -> "settled total = " + total
                + ", Rajesh=" + rajesh.getBalance() + ", Priya=" + priya.getBalance());

        // var is STATIC typing, not dynamic. The following would NOT compile:
        //   var s = "hello";
        //   s = 42;            // COMPILE ERROR: int cannot be assigned to String
        // var cannot be used for: fields, parameters, return types, or null:
        //   var x = null;      // COMPILE ERROR: cannot infer from null
    }
}

// ─── Would be in model/Account.java in a real project ───
class Account {
    private final String accountId;          // field: explicit type (var illegal here)
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {  // params: explicit
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/SettlementService.java in a real project ───
class SettlementService {
    private static final Logger log = Logger.getLogger(SettlementService.class.getName());

    // Return type must be explicit (var illegal); var used for LOCALS only.
    BigDecimal settle(Account from, Account to, List<BigDecimal> transfers) {
        var total = BigDecimal.ZERO;              // infers BigDecimal
        for (var amount : transfers) {            // infers BigDecimal (for-each)
            from.debit(amount);
            to.credit(amount);
            total = total.add(amount);
            log.fine(() -> "moved " + amount + " " + from.getAccountId()
                    + " -> " + to.getAccountId());
        }
        return total;
    }

    // var in try-with-resources; note full type arg on the right of the diamond.
    java.util.Map<String, BigDecimal> loadRates() {
        var rates = new java.util.HashMap<String, BigDecimal>();   // NOT <> (avoids Object)
        rates.put("INR", BigDecimal.ONE);
        return rates;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
